def _data_uri(inner: str) -> str:
    svg = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" '
        'stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' + inner + "</svg>"
    )
    return "data:image/svg+xml," + urllib.parse.quote(svg, safe="/:=,' ")


def icon_css(only=None) -> str:
    """CSS for every icon: <i class=ic-NAME></i> renders a recolourable glyph."""
    rules = [
        '[class^="ic-"],[class*=" ic-"]{display:inline-block;width:1.15em;height:1.15em;'
        "vertical-align:-0.2em;background-color:currentColor;flex:none;"
        "-webkit-mask:var(--ic) center/contain no-repeat;mask:var(--ic) center/contain no-repeat;}"
    ]
    for name, inner in ICONS.items():
        if only is not None and name not in only:
            continue
        rules.append(f'.ic-{name}{{--ic:url("{_data_uri(inner)}");}}')
    return "\n".join(rules)


def icon(name: str, size: str = "1.15em", color: str = "currentColor") -> str:
    """Inline icon markup for use inside HTML strings."""
    return f'<i class="ic-{name}" style="width:{size};height:{size};color:{color}"></i>'
